<div class="erp-cart"><template x-if="cart.length === 0"><div class="erp-cart-empty"><i class="ph ph-shopping-cart" aria-hidden="true"></i><p>Belum ada item</p><span>Tambahkan item untuk melanjutkan transaksi.</span></div></template><div id="cart-items-container"><template x-for="(item,index) in cart" :key="index"><button type="button" class="erp-cart-row cart-item" @click="item.typeProduct === 'parcel' ? openEditParcelModal(item) : openEditModal(item)"><span class="erp-record__avatar"><i class="ph ph-package" aria-hidden="true"></i></span><span class="erp-cart-identity"><strong x-text="item.name"></strong><span><span x-text="item.qty"></span> <span x-text="item.unit"></span> × Rp <span x-text="item.price.toLocaleString('id-ID')"></span></span><small x-show="item.discount > 0">Diskon Rp <span x-text="item.discount.toLocaleString('id-ID')"></span></small></span><span class="erp-cart-total">Rp <span x-text="(item.total_input || ((item.price * item.qty) - item.discount)).toLocaleString('id-ID')"></span><i class="ph ph-caret-right" aria-hidden="true"></i></span></button></template></div></div>